def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i > 0:
                dp[i][j][0] = max(dp[i][j][0], dp[i-1][j][0] + grid[i][j])
            if j > 0:
                dp[i][j][0] = max(dp[i][j][0], dp[i][j-1][0] + grid[i][j])
                if i > 0:
                    dp[i][j][1] = max(dp[i][j][1], dp[i-1][j-1][0] + grid[i][j])

    # The maximum value is either the sum of the two largest values in the last column and row
    max_value = max(dp[N-1][j][0] for j in range(N))
    max_value = max(max_value, dp[i][N-1][0] for i in range(N))
    if N > 1:
        max_value = max(max_value, dp[N-2][N-2][1] + grid[N-1][N-1])

