def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, k):
        if i == N:
            return 0
        if k == 0:
            return int(num_str[i:])

        max_val = 0
        for j in range(i, N):
            left = int(num_str[i:j+1])
            right = dp(j+1, k-1)
            max_val = max(max_val, left * right)

        return max_val

    return dp(0, K)
