def max_product(num_str: str, N: int, K: int) -> int:
    from collections import deque

    def multiply(a, b):
        return int(a) * int(b)

    def get_max_product(nums, k):
        max_heap = deque()
        for num in nums:
            max_heap.extend([num * multiplier for multiplier in max_heap])
            max_heap.append(num)

        while k > 0:
            max_heap.popleft()
            k -= 1

        return max(max_heap)

    if K == 0:
        return int(num_str)

    nums = [num_str[i:i+2] for i in range(0, N, 2)]
    return get_max_product(nums, K)
