def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == 'X':
                total += 10 * (10 - i)
            else:
                total += int(char) * (10 - i)
        return total % 11

    isbn_parts = isbn.split('-')
    isbn_without_check = isbn_parts[0] + isbn_parts[1] + isbn_parts[2]
    current_checksum = calculate_checksum(isbn_without_check)
    correct_checksum = 11 - (current_checksum % 11)
    if correct_checksum == 11:
        correct_checksum = 0
    if correct_checksum == 10:
        correct_checksum = 'X'

    if str(correct_checksum) == isbn_parts[-1]:
        return "Right"
    else:
        isbn_parts[-1] = str(correct_checksum)
        return '-'.join(isbn_parts)
