    right_min = [0] * n
    right_min[n - 1] = heights[n - 1]
    for i in range(n - 2, -1, -1):
        right_min[i] = min(right_min[i + 1], heights[i])

    max_choose = 0
    for i in range(n):
        if i == 0:
            max_choose = max(max_choose, right_min[i])
        elif i == n - 1:
            max_choose = max(max_choose, left_max[i])
        else:
            max_choose = max(max_choose, min(left_max[i], right_min[i]))

    return n - max_choose
