def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0

    # Find the peak index where heights start decreasing
    peak_index = 0
    for i in range(1, n):
        if heights[i] < heights[i - 1]:
            peak_index = i - 1
            break

    # If the peak is at the last index, no choir formation is possible
    if peak_index == n - 1:
        return n

    left_decreasing = heights[:peak_index + 1]
    right_decreasing = heights[peak_index:][::-1]

    # Find the longest increasing subsequence in the left part
    lis = [1] * len(left_decreasing)
    for i in range(1, len(left_decreasing)):
        for j in range(i):
            if left_decreasing[i] >= left_decreasing[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Find the longest increasing subsequence in the right part
    ris = [1] * len(right_decreasing)
    for i in range(1, len(right_decreasing)):
        for j in range(i):
            if right_decreasing[i] >= right_decreasing[j]:
                ris[i] = max(ris[i], ris[j] + 1)

    # The minimum students to leave is the total length minus the sum of LISS and LISR
    max_choir_length = max(max(lis), max(ris))
    return n - (max_choir_length - 1)
```

