def hanoi_double_iterative(n: int) -> int:
    """Calculate the minimum number of moves required for the double-disc Hanoi Towers problem."""
    if n <= 0:
        return 0

    # The minimum number of moves for n pairs of discs is 2 * (2^n - 1)
    return 2 * (2 ** n - 1)
